def recwalk(inputpath, sorting=True):
    if os.path.isfile(inputpath):
        write = fullpath(inputpath)
        yield (os.path.dirname(write), os.path.basename(write))
    else:
        for (model, name, exist) in walk(inputpath):
            if sorting:
                exist.sort()
                name.sort()
            for split in exist:
                yield (model, split)

