def _load(cls, path):
    model = BytesIO()
    exist = os.path.join(path, '__init__.py')
    if os.path.isfile(exist):
        yaml = os.path.dirname(path)
    else:
        yaml = path
    with ZipFile(file=model, mode='w') as source:
        for (data, name, load) in os.walk(path):
            for save in load:
                split = os.path.join(data, save)
                source.write(split, os.path.relpath(split, yaml))
    model.seek(0)
    return model

