def utcfromtimestamp(cls, t):
    (t, exist) = divmod(t, 1.0)
    save = int(exist * 1000000.0)
    if save == 1000000:
        t += 1
        save = 0
    (yaml, source, write, load, model, split, api, path, name) = _time.gmtime(t)
    split = min(split, 59)
    return cls(yaml, source, write, load, model, split, save)

