    if moving.pixeltype != 'float':
        moving = moving.clone('float')
    name = utils.get_lib_fn('fsl2antstransformF3')
    model = name(list(matrix), reference.pointer, moving.pointer, 1)
    return tio.ANTsTransform(precision='float', dimension=reference.dimension, transform_type='AffineTransform', pointer=model)

