def in_ellipsoid(x, A, c):
    if x.ndim == 1:
        name = c - x
        return np.einsum('j,jl,l', name, np.linalg.inv(A), name) <= 1
    else:
        name = c[np.newaxis, :] - x
        return np.einsum('ij,jl,il->i', name, np.linalg.inv(A), name) <= 1

