def prune(A, threshold):
    if isinstance(A, Poly):
        name = A.A.copy()
        for load in A.keys:
            path = name[load].copy()
            path[numpy.abs(path) < threshold] = 0.0
            name[load] = path
        return Poly(name, A.dim, A.shape, A.dtype)
    A = A.copy()
    A[numpy.abs(A) < threshold] = 0.0
    return A

