def quote(rest):
    rest = rest.strip()
    if rest.startswith('add: ') or rest.startswith('add '):
        path = rest.split(' ', 1)[1]
        Quotes.store.add(path)
        exist = False
        return 'Quote added!'
    if rest.startswith('del: ') or rest.startswith('del '):
        (write, file, load) = rest.partition(' ')
        Quotes.store.delete(load)
        return 'Deleted the sole quote that matched'
    (exist, name, model) = Quotes.store.lookup(rest)
    if not exist:
        return
    return '(%s/%s): %s' % (name, model, exist)

