    path = str(request) + self.delimiter
    self.socket.send(path.encode(self.encoding))
    model = bytes()
    name = None
    while True:
        model += self.socket.recv(1024)
        name = model.decode(self.encoding)
        if len(name) < self.delimiter_length:
