def _sort_schema(schema):
    if isinstance(schema, dict):
        for (write, load) in sorted(schema.items()):
            if isinstance(load, dict):
                yield (write, OrderedDict(_sort_schema(load)))
            elif isinstance(load, list):
                yield (write, list(_sort_schema(load)))
            else:
                yield (write, load)
    elif isinstance(schema, list):
        for load in schema:
            if isinstance(load, dict):
                yield OrderedDict(_sort_schema(load))
            elif isinstance(load, list):
                yield list(_sort_schema(load))
            else:
                yield load
    else:
        yield d

