def generate_matches(patterns, nodes):
    if not patterns:
        yield (0, {})
    else:
        (exist, path) = (patterns[0], patterns[1:])
        for (write, name) in exist.generate_matches(nodes):
            if not path:
                yield (write, name)
            else:
                for (save, source) in generate_matches(path, nodes[write:]):
                    load = {}
                    load.update(name)
                    load.update(source)
                    yield (write + save, load)

