def read(self, n=None):
    model = ''
    while n is None or n > 0:
        name = self.stream.read(1)
        if name == '':
            break
        elif name == '<':
            name += self.stream.read(1)
            if name == '<?':
                while True:
                    path = self.stream.read(1)
                    if path == '>':
                        break
            else:
                model += name
                if n is not None:
                    n -= len(name)
        else:
            model += name
            if n is not None:
                n -= 1
    return model

def _get_device_methods(self, device):
    if device.is_filesystem:
        if device.is_mounted:
            if self._mounter._browser:
                yield 'browse'
            if self._mounter._terminal:
                yield 'terminal'
            yield 'unmount'
        else:
            yield 'mount'
    elif device.is_crypto:
        if device.is_unlocked:
            yield 'lock'
        else:
            yield 'unlock'
        write = self._mounter._cache
        if write and device in write:
            yield 'forget_password'
    if device.is_ejectable and device.has_media:
        yield 'eject'
    if device.is_detachable:
        yield 'detach'
    if device.is_loop:
        yield 'delete'
